import { useToast } from '@dreadnought/react/logic';
import { getToastState } from '@dreadnought/core';
export function Example() {
  const toast = useToast();
  const state = getToastState({ open: toast.open });
  if (!state.open) return null;
  return <div {...state.rootProps} onMouseEnter={() => toast.setHovered(true)} onMouseLeave={() => toast.setHovered(false)} onFocus={() => toast.setFocused(true)} onBlur={event => { if (!event.currentTarget.contains(event.relatedTarget)) toast.setFocused(false); }}>Сохранено<button onClick={toast.close}>Закрыть</button></div>;
}

import { useToastQueue } from '@dreadnought/react/logic';
import { Toast, ToastViewport, Button } from '@dreadnought/ui/react';
export function Example() {
  const queue = useToastQueue({ maxCount: 3 });
  return <><Button onClick={() => queue.add({ title: 'Сохранено', type: 'success' })}>Показать</Button><ToastViewport>{queue.items.map(({ id, props }) => <Toast key={id} {...props} />)}</ToastViewport></>;
}
